\begin{theorem}[Long time existence improved]
\label{thm:chow-ii-appd-long-time-existence-ricci-blowup}
\source{chow-et-al-ricci-flow-part-ii:page-0385}
\uses{thm:chow-ii-appd-long-time-existence-closed}
\dcref{appD:D.6}
\group{Ricci Flow Existence}


Under the hypotheses of Theorem~\ref{thm:chow-ii-appd-long-time-existence-closed},
if $T<\infty$, then
\[
 \lim_{t\nearrow T}\sup_{x\in\mathcal M}|\operatorname{Ric}(x,t)|=\infty.
\]
\end{theorem}

